"""Apply the shared reading experience without changing the research record."""
from pathlib import Path
import re,json,html
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'assets/research-data.json').read_text())
E=lambda s:html.escape(str(s),quote=True)
init='<script src="assets/theme.js"></script>'

for p in R.rglob('*.html'):
 t=p.read_text();m=re.search(r'data-base="([^"]*)"',t)
 if not m:continue
 b=m[1]
 t=re.sub(r'<div class="reading-progress" aria-hidden="true"><span></span></div>','',t)
 t=t.replace('content="dark"','content="dark light"')
 t=re.sub(r'<script>\(function\(\)\{try\{var t=localStorage.*?</script>','',t)
 t=re.sub(r'<script src="[^"]*assets/theme.js[^"]*"></script>','',t)
 t=t.replace('<link rel="stylesheet"',f'<script src="{b}assets/theme.js"></script><link rel="stylesheet"',1)
 t=re.sub(r'<header class="mast">.*?</header>',f'''<header class="mast"><a class="top-brand" href="{b}index.html" aria-label="The SIR Files home"><span class="brand-symbol">S<span>↗</span></span>THE SIR <b>FILES</b></a><nav class="top-nav" aria-label="Explore"><a href="{b}state-files/">State files</a><a href="{b}claims/">Check a claim</a><a href="{b}evidence/">The sources</a></nav><div class="mast-right"><button class="theme-toggle" data-theme aria-label="Switch colour theme"><span data-theme-icon aria-hidden="true">◐</span><span data-theme-label>Theme</span></button><button data-search-open aria-label="Search all pages">⌕ <span>Search</span><kbd>⌘K</kbd></button><button class="mobile-menu" data-menu aria-label="Open site menu" aria-expanded="false">☰</button></div></header><div class="reading-progress" aria-hidden="true"><span></span></div>''',t,flags=re.S)
 t=t.replace('A DOCUMENTARY INVESTIGATION','FOLLOW THE RECORD')
 t=t.replace('>The publication<','>Find your way<').replace('>Open jurisdiction directory (36)<','>All 36 states &amp; Union Territories<')
 t=t.replace('>Latest Research <','>Latest review <').replace('>Claims Register <','>Check a claim <').replace('>Full Audit <','>What we checked <')
 if 'class="reading-tools"' not in t and p!=R/'index.html':
  t=t.replace('<main id="main" class="container">','<main id="main" class="container"><div class="reading-tools"><a href="'+b+'index.html">← Back to the story</a><button data-save>＋ Save for later</button><button data-share>↗ Share this page</button></div>',1)
 if p==R/'index.html':
  topics={'bihar':'The Supreme Court ruling and the limits of what it decides.','goa':'A signed report, balanced totals and individual outcomes still to audit.','west-bengal':'Court directions and the procedures for unresolved cases.','maharashtra':'Application counts, changing deadlines and the records still missing.','karnataka':'Bulk objections, Form 7 and the evidence needed to establish outcomes.','delhi':'Notices, responses and the missing record of what happened next.','uttarakhand':'All 13 district totals reconciled against the final report.','tripura':'A corrected deadline and a later timetable awaiting its signed source.'}
  states=''.join(f'''<a class="state-card" data-state="{E(j['name'].lower())}" data-scope="{'detailed' if j['depth']!='Reference file' else 'reference'}" href="state-files/{j['slug']}/"><span class="count">{'Closer look' if j['depth']!='Reference file' else 'Reference file'}</span><h3>{E(j['name'])}</h3><p>{E(topics.get(j['slug'],'Original schedule and reference sources. Detailed local evidence is still needed.'))}</p><span class="card-foot">Read the file <span>↗</span></span></a>''' for j in sorted(D['jurisdictions'],key=lambda j:(j['depth']=='Reference file',j['name'])))
  claims=''.join(f'''<details class="claim-preview"><summary><span class="status">{E(c['status'])}</span><h3>{E(c['claim'])}</h3><span class="detail-prompt">See what supports this +</span></summary><div class="claim-answer"><p>{E(c['limitation'])}</p><a href="claims/#{E(c['id'])}">Read the evidence and next steps →</a></div></details>''' for c in [D['claims'][0],D['claims'][1],next(c for c in D['claims'] if c['id']=='NAT-01')])
  timeline=''.join(f'<details class="timeline-item"{ " open" if i==3 else ""}><summary><span>{E(x[0])}</span><strong>{E(x[1])}</strong><b>+</b></summary><p>{E(x[2])}</p></details>' for i,x in enumerate(D['chronology'][-4:]))
  main=f'''<main id="main" class="container home"><section class="hero"><div class="hero-text"><div class="eyebrow"><span class="signal"></span> INDEPENDENT RESEARCH · INDIA’S ELECTORAL ROLLS</div><h1>Who stays on<br>the <em>voter list?</em></h1><p>India’s electoral rolls are being revised. We follow the orders, the numbers and the unresolved questions, so you can see what the evidence supports.</p><div class="button-row"><a class="button" href="#places">Explore your state <span>↗</span></a><a class="button outline" href="research/">Read the latest review ↗</a></div><p class="hero-note">SIR means Special Intensive Revision: preparing electoral rolls afresh. Start with the background if you’re new here.</p></div><a class="lead-story" href="state-files/goa/"><div class="story-top"><span>IN THE RECORD / GOA</span><span>↗</span></div><span class="story-type">THE NUMBERS, EXPLAINED</span><h2>The totals add up.<br>What about the decisions?</h2><p>Goa’s signed report lets us trace the draft-to-final change. It doesn’t settle whether every individual decision was correct.</p><div class="roll-comparison"><div><span>Draft roll</span><strong>1,084,992</strong></div><span aria-hidden="true">→</span><div><span>Final roll</span><strong>1,057,566</strong></div></div><div class="story-bottom"><span>Read the Goa analysis</span><span>→</span></div></a></section>
<div class="edition"><span><i class="signal"></i> Reviewed 17 October 2026</span><span>Sources checked through 16 October · This is a dated archive</span><a href="audit/">What we checked ↗</a></div>
<section id="start" class="section-block"><div class="section-head"><div><span class="eyebrow">START HERE</span><h2>What do you want to understand?</h2></div><p>Pick the question that brought you here.</p></div><div class="entry-grid"><a class="entry-card" href="history/"><span>01 <b>↗</b></span><h3>“What is SIR, anyway?”</h3><p>The backstory, the turning points, and why this became a national debate.</p><strong>Start with the story →</strong></a><a class="entry-card" href="#places"><span>02 <b>↘</b></span><h3>“What happened in my state?”</h3><p>Find the local record, the decisions we can trace, and the questions still open.</p><strong>Find your state →</strong></a><a class="entry-card" href="#claims"><span>03 <b>↘</b></span><h3>“Can I trust that claim?”</h3><p>Look past the headline. See the source, its limits, and what would change the answer.</p><strong>Check the evidence →</strong></a></div></section>
<section id="places" class="section-block"><div class="section-head"><div><span class="eyebrow">EXPLORE BY STATE</span><h2>Find your state.</h2></div><p>36 jurisdictions. Eight developed analyses.<br>28 reference files with work still to do.</p></div><div class="filterbar"><label>Find a state or Union Territory<input id="state-filter" type="search" placeholder="Try Goa, Bihar, Maharashtra…"></label><label>Show<select id="state-scope"><option value="detailed">The eight developed files</option><option value="all">All 36 jurisdictions</option><option value="reference">Reference files</option></select></label><span id="state-count" aria-live="polite">36 jurisdictions</span></div><div class="state-grid">{states}</div><p class="empty-state hidden" id="state-empty">No match yet. Try another state name or choose all jurisdictions.</p></section>
<section id="claims" class="section-block"><div class="section-head"><div><span class="eyebrow">CHECK THE EVIDENCE</span><h2>What does the evidence say?</h2></div><a class="more" href="claims/">All 20 claims →</a></div><p class="section-intro">Open a question. See where the evidence holds—and where it stops.</p><div class="claim-previews">{claims}</div><div class="principle"><span>KEEP THIS DISTINCTION IN MIND</span><p>A missing name on a draft roll is not automatically a final exclusion. A balanced spreadsheet doesn’t tell us whether every decision was fair.</p><a href="national/">Why the difference matters ↗</a></div></section>
<section class="section-block timeline-section"><div><span class="eyebrow">RECENT DEVELOPMENTS</span><h2>What changed recently?</h2><p>Four recent entries from the research chronology. Open each entry for context.</p><a class="more" href="history/">Read the full history →</a></div><div class="timeline">{timeline}</div></section>
<section class="closing"><span class="eyebrow">THE DOCUMENTS ARE OPEN</span><h2>Check our work.</h2><p>Every conclusion has limits. Read the original sources, our corrections and the questions we still need to answer.</p><div class="button-row"><a class="button" href="evidence/">Open the source library ↗</a><a class="button outline" href="investigations/">What we still don’t know →</a></div></section></main>'''
  t=re.sub(r'<main id="main" class="container".*?</main>',lambda _:main,t,flags=re.S)
 # Content-based asset addresses prevent new HTML from reusing an older script or stylesheet.
 for asset in ['site.css','site.js','search-data.js','theme.js']:
  import hashlib
  digest=hashlib.sha256((R/'assets'/asset).read_bytes()).hexdigest()[:12]
  t=re.sub(r'(assets/'+re.escape(asset)+r')(?:\?v=[a-zA-Z0-9-]+)?',lambda m:m[1]+'?v='+digest,t)
 p.write_text(t)
print('Updated shared navigation and homepage')
